import numpy as np
from scipy.optimize import minimize

def fun(x):
    if x[0] <= 0:
        return np.nan
    return x[0] - np.log(x[0])

def jac(x):
    if x[0] <= 0:
        return np.array([np.nan])
    return np.array([1.0 - 1.0/x[0]])

def hess(x):
    if x[0] <= 0:
        raise ValueError('Hessian evaluated outside domain')
    return np.array([[1.0/x[0]**2]])

try:
    result = minimize(fun, [2.1], jac=jac, hess=hess, method='trust-exact',
                     tol=1e-8, options={'initial_trust_radius': 10, 'maxiter': 10})
    probe('success', float(result.success))
    probe('x_0', float(result.x[0]))
    probe('nfev', float(result.nfev))
except ValueError as e:
    probe('error_type', 1.0)  # 1.0 indicates ValueError occurred
    probe('error_message_contains_hessian', 1.0 if 'Hessian' in str(e) else 0.0)
except Exception as e:
    probe('error_type', 2.0)  # 2.0 indicates other exception
    probe('exception_name', float(ord(str(type(e).__name__)[0])))  # encode exception type

